function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const storeSelect = container.querySelector("#store-select");
  const categoryFilter = container.querySelector("#category-filter");
  const productNameSearch = container.querySelector("#product-name-search");
  const productCodeSearch = container.querySelector("#product-code-search");
  const stockStatusFilter = container.querySelector("#stock-status-filter");
  const errorMessage = container.querySelector("#error-message");
  const resultCount = container.querySelector("#result-count");

  let allInventoryData = [];
  let storesData = [];
  let productsData = [];

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況判定関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況のスタイル取得
  function getStatusStyle(status) {
    switch(status) {
      case "不足":
        return "background: rgba(255, 106, 106, 0.2); color: #ff6a6a; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      case "過剰":
        return "background: rgba(255, 165, 0, 0.2); color: #ffa500; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      case "適正":
        return "background: rgba(34, 197, 94, 0.2); color: #22c55e; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;";
      default:
        return "color: var(--text-muted);";
    }
  }

  // テーブル再描画関数
  function renderRows(inventoryRows) {
    if (!inventoryRows || inventoryRows.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" style="text-align: center; color: var(--text-muted); padding: 40px;">
            該当する商品が見つかりませんでした
          </td>
        </tr>
      `;
      resultCount.textContent = "0";
      return;
    }

    tbody.innerHTML = inventoryRows.map(row => {
      const product = productsData.find(p => p.商品ID === row.商品ID) || {};
      const currentStock = row.現在在庫数 || 0;
      const safetyStock = row.安全在庫数 || 0;
      const status = getStockStatus(currentStock, safetyStock);
      const statusStyle = getStatusStyle(status);

      return `
        <tr data-id="${row.在庫ID || row.id}">
          <td>${product.商品コード || ""}</td>
          <td>${product.商品名 || ""}</td>
          <td style="text-align: right; ${currentStock === 0 ? 'color: #ff6a6a; font-weight: 600;' : ''}">${currentStock.toLocaleString()}</td>
          <td style="text-align: right;">${safetyStock.toLocaleString()}</td>
          <td><span style="${statusStyle}">${status}</span></td>
          <td style="color: var(--text-muted); font-size: 12px;">${row.更新日時 ? new Date(row.更新日時).toLocaleString() : ""}</td>
        </tr>
      `;
    }).join("");

    resultCount.textContent = inventoryRows.length.toString();
  }

  // 店舗データ読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storesData = stores.filter(store => store.有効フラグ);
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          storesData.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join("");
      }
    } catch (error) {
      console.error("店舗データの読み込みに失敗しました:", error);
    }
  }

  // 商品データ読み込み
  async function loadProducts() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productsData = products.filter(product => product.有効フラグ);

        // カテゴリ一覧を作成（重複除去）
        const categories = [...new Set(productsData.map(p => p.商品カテゴリID).filter(Boolean))];
        categoryFilter.innerHTML = '<option value="">全てのカテゴリ</option>' +
          categories.map(cat => `<option value="${cat}">カテゴリ${cat}</option>`).join("");
      }
    } catch (error) {
      console.error("商品データの読み込みに失敗しました:", error);
    }
  }

  // 検索実行
  async function performSearch() {
    const selectedStoreId = storeSelect.value;

    if (!selectedStoreId) {
      showError("店舗を選択してください");
      return;
    }

    try {
      // 在庫データを取得（実際のシステムでは在庫テーブルから取得）
      // ここではサンプルデータを生成
      const inventoryData = productsData.map(product => ({
        在庫ID: `inv-${product.商品ID}`,
        店舗ID: selectedStoreId,
        商品ID: product.商品ID,
        現在在庫数: Math.floor(Math.random() * 200),
        安全在庫数: Math.floor(Math.random() * 50) + 10,
        更新日時: new Date().toISOString()
      }));

      allInventoryData = inventoryData;

      // フィルタリング実行
      applyFilters();

    } catch (error) {
      console.error("検索に失敗しました:", error);
      showError("検索処理でエラーが発生しました");
    }
  }

  // フィルタ適用
  function applyFilters() {
    let filteredData = [...allInventoryData];

    // 商品カテゴリフィルタ
    const selectedCategory = categoryFilter.value;
    if (selectedCategory) {
      const categoryProducts = productsData.filter(p => p.商品カテゴリID === selectedCategory);
      const categoryProductIds = categoryProducts.map(p => p.商品ID);
      filteredData = filteredData.filter(inv => categoryProductIds.includes(inv.商品ID));
    }

    // 商品名検索
    const productNameKeyword = productNameSearch.value.trim();
    if (productNameKeyword) {
      // 特殊文字チェック
      if (/<script|javascript:|on\w+=/i.test(productNameKeyword)) {
        showError("不正な文字が含まれています");
        return;
      }

      // 最大文字数チェック
      if (productNameKeyword.length > 255) {
        showError("商品名は255文字以内で入力してください");
        return;
      }

      const matchingProducts = productsData.filter(p => 
        p.商品名 && p.商品名.includes(productNameKeyword)
      );
      const matchingProductIds = matchingProducts.map(p => p.商品ID);
      filteredData = filteredData.filter(inv => matchingProductIds.includes(inv.商品ID));
    }

    // 商品コード検索
    const productCodeKeyword = productCodeSearch.value.trim();
    if (productCodeKeyword) {
      // 特殊文字チェック
      if (/<script|javascript:|on\w+=/i.test(productCodeKeyword)) {
        showError("不正な文字が含まれています");
        return;
      }

      // 数値以外の文字チェック（英数字は許可）
      if (!/^[A-Za-z0-9]+$/.test(productCodeKeyword)) {
        showError("商品コードは英数字で入力してください");
        return;
      }

      // 最大桁数チェック
      if (productCodeKeyword.length > 20) {
        showError("商品コードは20桁以内で入力してください");
        return;
      }

      const matchingProducts = productsData.filter(p => 
        p.商品コード && p.商品コード.includes(productCodeKeyword)
      );
      const matchingProductIds = matchingProducts.map(p => p.商品ID);
      filteredData = filteredData.filter(inv => matchingProductIds.includes(inv.商品ID));
    }

    // 在庫状況フィルタ
    const selectedStatus = stockStatusFilter.value;
    if (selectedStatus) {
      filteredData = filteredData.filter(inv => {
        const status = getStockStatus(inv.現在在庫数, inv.安全在庫数);
        return status === selectedStatus;
      });
    }

    renderRows(filteredData);
  }

  // CSVエクスポート
  function exportCSV() {
    if (!allInventoryData || allInventoryData.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
    const csvData = allInventoryData.map(row => {
      const product = productsData.find(p => p.商品ID === row.商品ID) || {};
      const status = getStockStatus(row.現在在庫数, row.安全在庫数);

      return [
        product.商品コード || "",
        product.商品名 || "",
        row.現在在庫数 || 0,
        row.安全在庫数 || 0,
        status,
        row.更新日時 ? new Date(row.更新日時).toLocaleString() : ""
      ].map(field => `"${String(field).replace(/"/g, '""')}"`).join(",");
    });

    const csvContent = "\uFEFF" + [headers.join(","), ...csvData].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `inventory_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 検索条件クリア
  function clearSearchConditions() {
    storeSelect.value = "";
    categoryFilter.value = "";
    productNameSearch.value = "";
    productCodeSearch.value = "";
    stockStatusFilter.value = "";
    allInventoryData = [];
    tbody.innerHTML = `
      <tr>
        <td colspan="6" style="text-align: center; color: var(--text-muted); padding: 40px;">
          店舗を選択して検索してください
        </td>
      </tr>
    `;
    resultCount.textContent = "0";
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // リアルタイムフィルタリング
  categoryFilter.addEventListener("change", () => {
    if (allInventoryData.length > 0) {
      applyFilters();
    }
  });

  stockStatusFilter.addEventListener("change", () => {
    if (allInventoryData.length > 0) {
      applyFilters();
    }
  });

  // 初期データ読み込み
  loadStores();
  loadProducts();
}
